$stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
$services = 'bits','wuauserv','cryptsvc'
try {
  foreach ($service in $services) { Stop-Service -Name $service -Force -ErrorAction Stop }
  Rename-Item "$env:windir\SoftwareDistribution" "SoftwareDistribution.INTA-$stamp" -ErrorAction Stop
  Rename-Item "$env:windir\System32\catroot2" "catroot2.INTA-$stamp" -ErrorAction Stop
} finally {
  foreach ($service in $services) { Start-Service -Name $service -ErrorAction SilentlyContinue }
}
Get-Service -Name bits,wuauserv,cryptsvc | Format-Table Name,Status -AutoSize

$checks = @('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired','HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending')
$checks | ForEach-Object { [pscustomobject]@{Path=$_;Present=(Test-Path $_)} }
Get-Service -Name TrustedInstaller,wuauserv,msiserver -ErrorAction SilentlyContinue | Format-Table Name,Status -AutoSize
